private def separatingCoordinate (A B : Set ℕ) : ℕ :=
  if h : A = B then 0 else Classical.choose (show ∃ n, ¬ (n ∈ A ↔ n ∈ B) from
    not_forall.mp (fun hh => h (Set.ext hh)))

